import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.BB06nUeW.js";const u=JSON.parse('{"title":"Project Pitch: AegisBank","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),o={name:"00b-project-pitch.md"};function r(s,e,c,l,d,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="project-pitch-aegisbank" tabindex="-1">Project Pitch: AegisBank <a class="header-anchor" href="#project-pitch-aegisbank" aria-label="Permalink to &quot;Project Pitch: AegisBank&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built <strong>AegisBank</strong>, a secure digital banking and double-entry ledger platform built on the MERN stack with Express 5 and React 18. Unlike naive banking apps that simply update balance columns, AegisBank enforces immutable double-entry bookkeeping where every transfer generates balanced debit and credit ledger entries inside atomic MongoDB transactions. It features anti-IDOR authorization guards, brute-force security defenses, token blacklist logout, and instant CSV statement generation.&quot;</p><h2 id="_2-minute-spoken-pitch" tabindex="-1">2-Minute Spoken Pitch <a class="header-anchor" href="#_2-minute-spoken-pitch" aria-label="Permalink to &quot;2-Minute Spoken Pitch&quot;">​</a></h2><p>&quot;Building financial software requires zero tolerance for data inconsistency. If two transfer requests arrive within three milliseconds of each other on an account with a $100 balance, a poorly engineered system could allow both to withdraw, resulting in an unauthorized negative balance.</p><p>To eliminate this vulnerability, I engineered AegisBank:</p><p>First, at the core of the financial engine in <code>transaction.controller.js</code>, I implemented an immutable double-entry bookkeeping model. Every financial movement generates two synchronized ledger entries in <code>ledger.model.js</code>—a debit against the sender and an offsetting credit to the recipient. The sum of all debits and credits across the system must mathematically balance to zero.</p><p>Second, transfers execute inside atomic MongoDB sessions. The engine verifies account ownership, rejects negative amounts or self-transfers, locks the source account, checks available balance, and atomically commits the balance changes and ledger records. If any step fails, the entire transaction rolls back cleanly.</p><p>Third, for security, our authentication middleware in <code>auth.controller.js</code> checks every incoming JWT against our <code>blackList.model.js</code>. When a customer logs out, their token is immediately blacklisted with a TTL expiry matching the token lifetime, preventing replay attacks if a token is intercepted.</p><p>Finally, on the frontend, I developed a clean React 18 single-page application with Axios request interceptors, real-time balance refreshes, payee beneficiary management, and automated CSV statement exports.</p><p>The application is thoroughly verified with 17 automated unit and security tests asserting ledger immutability and IDOR protections.&quot;</p>',11)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
